const lead = $input.item.json;
const msgs = {
  '7d':  `Oi ${lead.nome}! 😊

Passou uma semana desde que conversamos sobre a Odara Rio.

Ainda está pensando em cuidar de você? A gente adoraria te receber! ✨

Quer marcar uma avaliação gratuita?`,
  '30d': `${lead.nome}, oi! 💙

Um mês atrás você demonstrou interesse na Odara Rio e gostaríamos de saber: como está você?

Nossos protocolos estão cada vez mais incríveis! Que tal darmos uma nova chance? 🌸`,
  '60d': `Oi ${lead.nome}! Faz tempo... 🥺

Sabemos que a vida é corrida, mas nunca é tarde para começar a cuidar de você!

Temos uma condição especial esperando por você. Vamos conversar? 💆‍♀️`
};
return { json: { ...lead, mensagem: msgs[lead.sequencia] || '' } };
